/**
 * The edge functions' email texts come from messages/{en,no}/mail.json, like every other text (CLAUDE.md: i18n). An edge
 * function is deployed without the repository around it, so this writes them into supabase/functions/_shared/mail-texts.gen.ts.
 * The CSAT question in a resolution email and the csat function's answers (0081) live with the screen that reads the
 * scores, in messages/{en,no}/support-hub.json (supportHub.csat), and are carried here as `csat`.
 * tests/mail.test.ts fails when the generated file and the messages disagree.
 *
 *   node scripts/mail-texts.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs'

const read = (path) => JSON.parse(readFileSync(new URL(path, import.meta.url), 'utf8'))

export function mailTextsSource() {
  const en = { ...read('../messages/en/mail.json').mail, csat: read('../messages/en/support-hub.json').supportHub.csat }
  const no = { ...read('../messages/no/mail.json').mail, csat: read('../messages/no/support-hub.json').supportHub.csat }
  return `// Generated by scripts/mail-texts.mjs from messages/{en,no}/mail.json and supportHub.csat. Do not edit.\nexport const MAIL_TEXTS = ${JSON.stringify({ en, no }, null, 2)} as const\n`
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const target = new URL('../supabase/functions/_shared/mail-texts.gen.ts', import.meta.url)
  writeFileSync(target, mailTextsSource())
  console.log('wrote supabase/functions/_shared/mail-texts.gen.ts')
}
